import asyncio
from pathlib import Path

from app.services.superdocs_service import SuperDocsClient


async def main() -> None:
    # Use the HTML generated by our existing report pipeline.
    html_path = Path("sample_upload_report.html")

    html_content = """
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Daily Field Report</title>
</head>
<body>
    <h1>Daily Field Report</h1>

    <p>
        18 workers were onsite today.
    </p>

    <p>
        Concrete work was completed in Zone A.
    </p>

    <p>
        The excavator was stopped for two hours because
        of a hydraulic issue.
    </p>
</body>
</html>
"""

    html_path.write_text(
        html_content,
        encoding="utf-8",
    )

    client = SuperDocsClient()

    session_id = "daily-field-document-test"

    print("Uploading document...")

    result = await client.upload_document(
        session_id=session_id,
        file_path=html_path,
    )

    print("\nUpload response:")
    print(result)


if __name__ == "__main__":
    asyncio.run(main())